head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDINF90500";

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        await scwin.init_loadList();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldinf90500.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_itemId", fn: function () { return String((dma_pageContext.get("itemId") ?? "")); } },
        { childId: "ipt_itemNm", fn: function () { return String((dma_pageContext.get("itemNm") ?? "")); } },
        { childId: "ipt_insType", fn: function () { return String((dma_pageContext.get("insType") ?? "")); } },
        { childId: "ipt_searchType", fn: function () { return String((dma_pageContext.get("searchType") ?? "")); } },
        { childId: "ipt_searchWord", fn: function () { return String((dma_pageContext.get("searchWord") ?? "")); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        $c.util.getComponent("ipt_searchWord").focus();
        $c.util.getComponent('ipt_searchWord').setValue(($c.util.getComponent("ipt_searchWord").getValue() || ''));

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf90500.onpageload' }); }
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_submit). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fn_Search();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description btn_Search 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function(e){
    try {
        await scwin.search()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf90500.btn_Search_onclick' }); }
};

/**
 * @method
 * @name grd_resultList_oncellclick
 * @description grd_resultList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_resultList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_resultList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_resultList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        scwin.send_form(r["stdCd"], r["isuNm"], r["isuEngNm"], r["isurCd"], r["isuDate"], r["redmptDate"], r["isuAmt"], r["rdmpYyyy"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_resultList.oncellclick' });
    }
};

/**
 * @method
 * @name btn_window_onclick
 * @description btn_window 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_window_onclick = function(e){
    try {
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf90500.btn_window_onclick' }); }
};

/**
 * @method
 * @name btn_window_onfocus
 * @description btn_window 포커스 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_window_onfocus = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        selfVar.blur()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf90500.btn_window_onfocus' }); }
};

/**
 * @method
 * @name __on_enter_1_ipt_searchword
 * @description on enter 1 ipt searchword 처리
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.__on_enter_1_ipt_searchword = async function(e){
    try {
        const ev = e;
        if(($c.util.getKeyCode(ev))===13){ await scwin.search() }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf90500.__on_enter_1_ipt_searchWord' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Search
 * @description Search 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Search = async function (action) {
    const sbmOptions = {
        id: "tx_fn_Search",
        method: "post",
        action: action ?? "/common/stdcd.do?method=tgtBndStdCd",
        ref: "dma_SearchReq",
        target: "dlt_resultList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    const search_type = $c.util.getComponent('dma_SearchReq').get('searchType');
    await scwin.tx_fn_Search('/common/stdcd.do?method=tgtBndStdCd');
};

/**
 * @method
 * @name send_form
 * @description send form 처리
 * @param {*} std_cd std_cd
 * @param {*} com_nm com_nm
 * @param {*} eng_nm eng_nm
 * @param {*} isur_cd isur_cd
 * @param {*} isu_dd isu_dd
 * @param {*} redmpt_dd redmpt_dd
 * @param {*} isu_amt isu_amt
 * @param {*} rdmp_yyyy rdmp_yyyy
 * @returns {void}
 * @hidden N
 */
scwin.send_form = function (std_cd, com_nm, eng_nm, isur_cd, isu_dd, redmpt_dd, isu_amt, rdmp_yyyy) {
    const ins_type = $c.util.getComponent('ipt_insType').getValue();
    if (ins_type === 'strip') {
        ((scwin.opener().getComponentById("f_obj_isu_cd")) && (scwin.opener().getComponentById("f_obj_isu_cd")).setValue ? (scwin.opener().getComponentById("f_obj_isu_cd")).setValue(std_cd) : (console.warn('[sdd] 부모 컴포넌트 미해결: ' + "f_obj_isu_cd"), void (std_cd)));
        ((scwin.opener().getComponentById("f_v_isu_nm")) && (scwin.opener().getComponentById("f_v_isu_nm")).setValue ? (scwin.opener().getComponentById("f_v_isu_nm")).setValue(com_nm) : (console.warn('[sdd] 부모 컴포넌트 미해결: ' + "f_v_isu_nm"), void (com_nm)));
        ((scwin.opener().getComponentById("f_v_isu_eng_nm")) && (scwin.opener().getComponentById("f_v_isu_eng_nm")).setValue ? (scwin.opener().getComponentById("f_v_isu_eng_nm")).setValue(eng_nm) : (console.warn('[sdd] 부모 컴포넌트 미해결: ' + "f_v_isu_eng_nm"), void (eng_nm)));
        ((scwin.opener().getComponentById("isurCd")) && (scwin.opener().getComponentById("isurCd")).setValue ? (scwin.opener().getComponentById("isurCd")).setValue(isur_cd) : (console.warn('[sdd] 부모 컴포넌트 미해결: ' + "isurCd"), void (isur_cd)));
        ((scwin.opener().getComponentById("f_v_isu_dd")) && (scwin.opener().getComponentById("f_v_isu_dd")).setValue ? (scwin.opener().getComponentById("f_v_isu_dd")).setValue(isu_dd) : (console.warn('[sdd] 부모 컴포넌트 미해결: ' + "f_v_isu_dd"), void (isu_dd)));
        ((scwin.opener().getComponentById("f_redmpt_dd")) && (scwin.opener().getComponentById("f_redmpt_dd")).setValue ? (scwin.opener().getComponentById("f_redmpt_dd")).setValue(redmpt_dd) : (console.warn('[sdd] 부모 컴포넌트 미해결: ' + "f_redmpt_dd"), void (redmpt_dd)));
        ((scwin.opener().getComponentById("f_v_exp_isu_amt")) && (scwin.opener().getComponentById("f_v_exp_isu_amt")).setValue ? (scwin.opener().getComponentById("f_v_exp_isu_amt")).setValue(isu_amt) : (console.warn('[sdd] 부모 컴포넌트 미해결: ' + "f_v_exp_isu_amt"), void (isu_amt)));
        /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
        ((scwin.opener().getComponentById("f_rdmp_yyyy")) && (scwin.opener().getComponentById("f_rdmp_yyyy")).setValue ? (scwin.opener().getComponentById("f_rdmp_yyyy")).setValue(rdmp_yyyy) : (console.warn('[sdd] 부모 컴포넌트 미해결: ' + "f_rdmp_yyyy"), void (rdmp_yyyy)));
        (((scwin.openerScwin()) !== scwin && typeof (scwin.openerScwin()).refreshPage === 'function' ? (scwin.openerScwin()).refreshPage() : void 0), $c.win.closePopup([]));
    } else {
        const item_id = $c.util.getComponent('dma_SearchReq').get('itemId');
        const item_nm = $c.util.getComponent('dma_SearchReq').get('itemNm');
        ((scwin.opener().getComponentById(item_id)) || { setValue: function () {} }).setValue(std_cd);
        ((scwin.opener().getComponentById(item_nm)) || { setValue: function () {} }).setValue(com_nm);
    }
    $c.win.closePopup();
};

/**
 * @method
 * @name opener
 * @description 부모 화면 scope(browserPopup/pageFramePopup 공통 — $c.win.getOpenerScope). 단독 진입이거나 부모가 닫혀 없으면
 * @returns {Object} 부모 화면 scope 또는 빈 scope
 * @hidden N
 */
scwin.opener = function () {
    const scope = ($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null;
    return scope || { getComponentById: function () { return null; }, scwin: {} };
};

/**
 * @method
 * @name openerScwin
 * @description 부모 화면의 scwin(함수·전역 접근용). 부모가 없으면 빈 객체
 * @returns {Object} 부모 scwin 또는 {}
 * @hidden N
 */
scwin.openerScwin = function () {
    return scwin.opener().scwin || {};
};
